import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as spla, random
from reference import Task

def passes(tol):
    for seed in random.sample(range(1000000), 100):
        problem=Task().generate_problem(n=300, random_seed=seed)
        A=problem['matrix']; k=problem['k']; N=A.shape[0]
        try:
            w_fast,v_fast = spla.eigs(A,k=k,v0=np.ones(N),ncv=20,tol=tol,maxiter=N*200)
        except Exception as e:
            print('ARPACK error',e); return False
        w_ref,v_ref = spla.eigs(A,k=k,v0=np.ones(N),ncv=20,tol=0,maxiter=N*200)
        # sort by modulus
        idx_fast=np.argsort(-np.abs(w_fast)); v_fast=v_fast[:,idx_fast]
        idx_ref=np.argsort(-np.abs(w_ref)); v_ref=v_ref[:,idx_ref]
        # compare each eigenvector
        for i in range(k):
            sim=np.abs(np.dot(np.conj(v_ref[:,i]), v_fast[:,i])/(np.linalg.norm(v_ref[:,i])*np.linalg.norm(v_fast[:,i])))
            if not np.isclose(sim,1.0, atol=1e-6):
                # print('fail similarity',1-sim, 'tol',tol)
                return False
    return True

for tol in [0,1e-8,1e-7,1e-6,1e-5]:
    print('tol', tol, passes(tol))
